@Composable
fun PlayPauseButton(
    isPlaying: Boolean,
    isLoading: Boolean,
    onPlay: () -> Unit,
    onPause: () -> Unit,
    containerColor: Color = MaterialTheme.colorScheme.primary,
    iconTint: Color = MaterialTheme.colorScheme.onPrimary,
) {
    var isPressed by remember { mutableStateOf(false) }
    val scale = remember { Animatable(1f) }

    LaunchedEffect(isPressed) {
        if (isPressed) {
            scale.animateTo(0.9f, animationSpec = spring(dampingRatio = 0.8f))
            scale.animateTo(1f, animationSpec = spring(dampingRatio = 0.4f))
        }
    }

    LaunchedEffect(isPlaying) {
        scale.animateTo(1.15f, animationSpec = spring(dampingRatio = 0.5f))
        scale.animateTo(1f, animationSpec = spring(dampingRatio = 0.5f))
    }

    IconButton(
        onClick = {
            isPressed = true
            if (isPlaying) onPause() else onPlay()
        },
        modifier = Modifier
            .size(72.dp)
            .scale(scale.value)
            .background(color = containerColor, shape = CircleShape),
    ) {
        if (isLoading) {
            CircularProgressIndicator(
                modifier = Modifier.size(32.dp),
                color = iconTint,
                strokeWidth = 3.dp,
            )
        } else {
            Icon(
                painter = if (isPlaying) painterResource(R.drawable.ic_pause) else painterResource(R.drawable.ic_play),
                contentDescription = if (isPlaying) stringResource(R.string.pause) else stringResource(R.string.play),
                modifier = Modifier.size(40.dp),
                tint = iconTint,
            )
        }
    }
}

@Composable
fun PlayModeButton(
    playMode: PlayMode,
    onClick: () -> Unit,
    tint: Color = MaterialTheme.colorScheme.onSurface,
) {
    val icon = when (playMode) {
        PlayMode.SEQUENTIAL -> painterResource(R.drawable.ic_shuffle_disabled)
        PlayMode.SHUFFLE -> painterResource(R.drawable.ic_shuffle)
        PlayMode.SINGLE_LOOP -> painterResource(R.drawable.ic_repeat_one)
        PlayMode.REPEAT_ALL -> painterResource(R.drawable.ic_repeat)
    }

    val label = when (playMode) {
        PlayMode.SEQUENTIAL -> stringResource(R.string.mode_sequential)
        PlayMode.SHUFFLE -> stringResource(R.string.mode_shuffle)
        PlayMode.SINGLE_LOOP -> stringResource(R.string.mode_single_loop)
        PlayMode.REPEAT_ALL -> stringResource(R.string.mode_repeat_all)
    }

    IconButton(onClick = onClick) {
        Icon(painter = icon, contentDescription = label, modifier = Modifier.size(28.dp), tint = tint)
    }
}

@Composable
fun ControlButton(icon: Painter, onClick: () -> Unit, size: Dp = 48.dp, tint: Color = MaterialTheme.colorScheme.onSurface) {
    IconButton(onClick = onClick, modifier = Modifier.size(size)) {
        Icon(painter = icon, contentDescription = null, modifier = Modifier.size(size * 0.65f), tint = tint)
    }
}

package com.winter.muplayer.ui.components

import android.content.Context
import android.graphics.Bitmap
import android.graphics.Color
import coil.ImageLoader
import coil.request.ImageRequest
import com.winter.muplayer.model.Track
import java.io.File

/** ms → "MM:SS" */
fun formatDuration(durationMs: Long): String {
    if (durationMs <= 0) return "--:--"
    val totalSeconds = durationMs / 1000
    val minutes = totalSeconds / 60
    val seconds = totalSeconds % 60
    return "%d:%02d".format(minutes, seconds)
}

/** 根据封面亮度计算自适应文字/图标颜色 */
fun computeAdaptiveTint(bitmap: Bitmap): androidx.compose.ui.graphics.Color {
    var r = 0f; var g = 0f; var b = 0f; var count = 0
    val step = maxOf(1, bitmap.width / 8)
    for (x in 0 until bitmap.width step step) {
        for (y in 0 until bitmap.height step step) {
            val pixel = bitmap.getPixel(x, y)
            r += Color.red(pixel); g += Color.green(pixel); b += Color.blue(pixel)
            count++
        }
    }
    if (count > 0) { r /= count; g /= count; b /= count }
    val luminance = (0.299 * r + 0.587 * g + 0.114 * b) / 255.0
    return if (luminance > 0.5) androidx.compose.ui.graphics.Color.Black.copy(alpha = 0.87f)
    else androidx.compose.ui.graphics.Color.White.copy(alpha = 0.87f)
}

/** 获取专辑封面本地缓存 URI */
fun getAlbumArtUri(track: Track, coverCache: Map<Long, String>): String? {
    return coverCache[track.id] ?: run {
        if (track.albumId > 0L) {
            "content://media/external/audio/albumart/${track.albumId}"
        } else null
    }
}

/** 后台封面缓存（图片加载 + 磁盘写入），复用 Coil 全局 ImageLoader 避免每次新建 */
suspend fun cacheCoverFiles(context: Context, tracks: List<Track>, coverCache: MutableMap<Long, String>) {
    val cacheDir = File(context.cacheDir, "album_covers")
    cacheDir.mkdirs()
    val loader = coil.ImageLoader(context.applicationContext)
    for (track in tracks) {
        val coverFile = File(cacheDir, "${track.id}.jpg")
        if (coverFile.exists()) {
            coverCache[track.id] = coverFile.absolutePath
            continue
        }
        try {
            if (track.albumId > 0L) {
                val request = ImageRequest.Builder(context)
                    .data("content://media/external/audio/albumart/${track.albumId}")
                    .size(200, 200)
                    .crossfade(false)
                    .memoryCacheKey("cover_${track.id}")
                    .build()
                val bitmap = (loader.execute(request).drawable
                    as? android.graphics.drawable.BitmapDrawable)?.bitmap ?: continue
                cacheDir.mkdirs()
                java.io.FileOutputStream(coverFile).use { fos ->
                    bitmap.compress(Bitmap.CompressFormat.JPEG, 85, fos)
                }
                coverCache[track.id] = coverFile.absolutePath
            }
        } catch (_: Exception) { }
    }
}

/** 计算封面缓存目录大小 */
fun computeCoverCacheSize(context: Context): String {
    val cacheDir = File(context.cacheDir, "album_covers")
    if (!cacheDir.isDirectory) return "0 KB"
    val total = cacheDir.walkTopDown().filter { it.isFile }.sumOf { it.length() }
    return when {
        total < 1024 -> "${total} B"
        total < 1024 * 1024 -> "${total / 1024} KB"
        else -> "${total / (1024 * 1024)} MB"
    }
}

