package com.winter.muplayer.config

import androidx.compose.runtime.compositionLocalOf
import androidx.compose.runtime.staticCompositionLocalOf

/**
 * 组件条目 —— 一个组件实例在 slot 中的声明。
 * @param id       组件注册 ID（字符串简写或 JSON key 去掉 # 前缀后的值）
 * @param cid      可选实例标识，用于 CSS 精准匹配（`#<cid>` 规则覆盖 `#<id>` 规则）
 * @param extra    组件行为/配置参数，由 JSON 对象属性指定
 * @param isCustom 原始写法是否带 `#` 前缀（未找到自定义定义时回退内置组件并输出警告）
 */
data class ComponentEntry(
    val id: String,
    val cid: String? = null,
    val extra: Map<String, Any?> = emptyMap(),
    val isCustom: Boolean = false,
)

/**
 * 组件插槽配置 —— JSON 根级 key 即为 slot 名。
 *
 * 每个 slot 的 value 是组件数组，每项可以是：
 * - 字符串：`"#app-name"`（不带 extra）
 * - 对象：`{ "#button": { "action": "play" } }`（extra 为 cid/class 外的属性）
 *
 * 示例：
 *   {
 *     "app-top": ["#app-name", "#search-button", "#setting-button", "#search-bar"],
 *     "app-center": ["#tab-bar", "#sort", "#playlist"],
 *     "app-bottom": ["#playbar"]
 *   }
 */
/**
 * 自定义组件定义 —— 用户通过 JSON 声明的组件。
 * @param icon drawable 资源名，如 `"ic_search"`
 * @param onClick 点击行为标识，如 `"toggleSearch"`、`"openSettings"`
 */
data class CustomComponentDef(
    val icon: String? = null,
    val onClick: String? = null,
)

data class ComponentLayout(
    val slots: Map<String, List<ComponentEntry>> = defaultSlots,
    /** 自定义组件定义 —— JSON 中以 `#name` 为 key 的条目 */
    val customComponents: Map<String, Map<String, Any?>> = emptyMap(),
    /** 全屏播放器 slot 定义 —— fp-slots JSON key 解析至此，JSON 未定义时回退默认值 */
    val fullPlayerSlots: Map<String, List<ComponentEntry>> = defaultFullPlayerSlots,
) {
    companion object {
        val defaultSlots: Map<String, List<ComponentEntry>> = mapOf(
            "app-top" to listOf(
                ComponentEntry("app-name"),
                ComponentEntry("spacer"),
                ComponentEntry("search-button"),
                ComponentEntry("setting-button"),
            ),
            "app-center" to listOf(
                ComponentEntry("tab-bar"),
                ComponentEntry("sort"),
                ComponentEntry("playlist"),
            ),
            "app-bottom" to listOf(ComponentEntry("playbar")),
        )

        /** 全屏播放器默认 slot 定义 —— 三个子区域竖向堆叠 */
        val defaultFullPlayerSlots: Map<String, List<ComponentEntry>> = mapOf(
            "main" to listOf(
                ComponentEntry("track-info"),
                ComponentEntry("progress-bar"),
                ComponentEntry("controls-row"),
            ),
        )
    }
}

val LocalComponentLayout = compositionLocalOf { ComponentLayout() }

/** 当前组件实例的 cid（如 JSON 中声明了 cid 字段），供组件自身或 CSS 调试使用。 */
val LocalComponentCid = staticCompositionLocalOf<String?> { null }

package com.winter.muplayer.config

import androidx.compose.foundation.layout.Box
import androidx.compose.runtime.compositionLocalOf
import androidx.compose.runtime.Composable
import androidx.compose.ui.Modifier
import androidx.compose.ui.Alignment
import androidx.compose.ui.graphics.Color
import com.winter.muplayer.core.MusicPlayerCore
import com.winter.muplayer.core.ProgressTracker
import com.winter.muplayer.model.PlayMode
import com.winter.muplayer.model.PlayerStateData
import com.winter.muplayer.model.Track

/**
 * 组件上下文 —— 所有注册组件通过 CompositionLocal 获取。
 * 包含渲染可能需要的所有 state 和回调。
 */
class SlotContext(
    /** 当前渲染的插槽名 */
    val slotName: String,
    // ── 搜索（改为全屏入口）──
    val onOpenSearch: () -> Unit,
    val onOpenSettings: () -> Unit,
    // ── 歌单 ──
    val localMusicList: List<Track>,
    val isLoadingLocal: Boolean,
    val coverCache: Map<Long, String>,
    val musicPlayerCore: MusicPlayerCore,
    val onPlayTrackSmart: (Track, List<Track>) -> Unit,
    // ── 播放控制 ──
    val playerState: PlayerStateData,
    val onPlay: () -> Unit,
    val onPause: () -> Unit,
    val onNext: () -> Unit,
    val onPrevious: () -> Unit,
    val onOpenFullPlayer: () -> Unit,
    val onOpenQueue: () -> Unit,
    // ── 全屏播放器专属 ──
    val onSeek: (Long) -> Unit = { _ -> },
    val onPlayModeChange: (PlayMode) -> Unit = {},
    val playMode: PlayMode = PlayMode.SEQUENTIAL,
    val adaptiveTint: Color = Color.Unspecified,
    /** 父 slot 的 CSS arrange 值（"row"/"column"/null），组件可据此切换竖向/横向布局 */
    val slotArrange: String? = null,
)

/** 父 slot 为横向排列（arrange: row/horizontal） */
val SlotContext.isSlotHorizontal: Boolean
    get() = slotArrange == "row" || slotArrange == "horizontal"

/** 父 slot 为竖向排列（arrange: column/vertical 或未设置） */
val SlotContext.isSlotVertical: Boolean
    get() = !isSlotHorizontal

/** CompositionLocal 承载当前 slot 上下文 */
val LocalSlotContext = compositionLocalOf<SlotContext> {
    error("SlotContext not provided — wrap SlotRenderer in CompositionLocalProvider")
}

/** CompositionLocal 承载当前组件的 extra 属性（来自 JSON layout） */
val LocalComponentExtra = compositionLocalOf<Map<String, Any?>> { emptyMap() }

/** CompositionLocal 承载当前播放进度 —— 独立于 playerState，仅进度条订阅，避免高频进度更新拖垮全 UI 重组 */
val LocalProgress = compositionLocalOf { ProgressTracker.ProgressData() }

/**
 * 组件注册表 —— 全局单例。
 * 任意模块调用 register(id) 注册自己的 Composable 渲染器，
 * JSON 布局文件中以 #id 引用即可自动渲染。
 */
object ComponentRegistry {

    private val registry = mutableMapOf<String, @Composable SlotContext.() -> Unit>()

    /** 注册一个组件渲染器 */
    fun register(id: String, renderer: @Composable SlotContext.() -> Unit) {
        registry[id] = renderer
    }

    /** 根据 ID 渲染组件，modifier 包裹组件（来自 CSS 样式）；未注册时静默跳过 */
    @Composable
    fun render(id: String, modifier: Modifier = Modifier) {
        val ctx = LocalSlotContext.current
        val css = LocalComponentCss.current
        val contentAlign = css["content-align"]?.let { parseContentAlign(it) } ?: Alignment.Center
        registry[id]?.let {
            Box(modifier = modifier, contentAlignment = contentAlign) { ctx.it() }
        }
    }

    /** 批量注册（内置组件用） */
    fun registerAll(vararg entries: Pair<String, @Composable SlotContext.() -> Unit>) {
        entries.forEach { (id, renderer) -> register(id, renderer) }
    }
}

package com.winter.muplayer.config

/**
 * 轻量 CSS 解析器 —— 支持 .class 和 #id 选择器。
 *
 * 支持格式：
 *   .class-name {
 *     property: value;
 *   }
 *   #component-id {
 *     property: value;
 *   }
 *
 * key 规则：
 *   .slot-name { }  → key ".slot-name"  （slot 样式）
 *   #component { }  → key "#component"  （组件样式）
 *
 * 不支持：伪类、组合器、@规则、多级选择器。
 */
object CssParser {

    // 匹配 .name { } 或 #name { }，保留前缀作为 key
    private val BLOCK_REGEX = Regex("""([.#])([\w-]+)\s*\{([^}]*)\}""")

    /** 解析 CSS 文本，返回 selector → 属性字典（保留 . / # 前缀） */
    fun parse(cssText: String): Map<String, Map<String, String>> {
        if (cssText.isBlank()) return emptyMap()
        val cleaned = removeComments(cssText)
        if (cleaned.isBlank()) return emptyMap()
        val rules = mutableMapOf<String, Map<String, String>>()

        for (match in BLOCK_REGEX.findAll(cleaned)) {
            val prefix = match.groupValues[1]    // "." 或 "#"
            val name = match.groupValues[2]      // "app-top" 或 "app-name"
            val body = match.groupValues[3].trim()
            val key = prefix + name               // ".app-top" 或 "#app-name"
            val props = parseProperties(body)
            if (props.isNotEmpty()) {
                rules[key] = props
            }
        }

        return rules
    }

    /** 从 CSS 块内解析属性 key: value */
    private fun parseProperties(body: String): Map<String, String> {
        val props = mutableMapOf<String, String>()
        // 按 ; 分割，然后解析每个 key: value
        val parts = body.split(";").map { it.trim() }.filter { it.isNotEmpty() }
        for (part in parts) {
            val colonIdx = part.indexOf(':')
            if (colonIdx > 0) {
                val key = part.substring(0, colonIdx).trim()
                val value = part.substring(colonIdx + 1).trim()
                if (key.isNotEmpty() && value.isNotEmpty()) {
                    props[key] = value
                }
            }
        }
        return props
    }

    /** 剔除 /* */ 注释 */
    private fun removeComments(text: String): String {
        val sb = StringBuilder(text.length)
        var i = 0
        while (i < text.length) {
            if (i + 1 < text.length && text[i] == '/' && text[i + 1] == '*') {
                i += 2
                while (i + 1 < text.length && !(text[i] == '*' && text[i + 1] == '/')) i++
                i += 2
            } else {
                sb.append(text[i])
                i++
            }
        }
        return sb.toString()
    }
}

package com.winter.muplayer.config

import org.json.JSONArray
import org.json.JSONObject
import java.io.File

/**
 * JSON 布局配置文件解析器。
 *
 * 每个 slot value 是组件数组，每项支持两种格式：
 * - 字符串：`"app-name"` → ComponentEntry("app-name", isCustom=false)
 *           `"#my-button"` → ComponentEntry("my-button", isCustom=true)
 *           `"#my-button@my-id"` → ComponentEntry("my-button", cid="my-id", isCustom=true)
 * - 对象（单 key，value 是对象）：
 *   `{ "#button": { "action": "play" } }` → 自定义组件（# 前缀）
 *   `{ "icon": { "icon": "ic_search" } }` → 内置组件（无 # 前缀）
 *   `{ "#icon@search-icon": { "icon": "ic_search" } }` → 带 cid（@ 语法）
 *   cid 只能从 key 的 @ 语法取，value 中声明无效
 *   保留 key（不进 extra）：class / name / children
 * - 对象（多 key 或所有 value 都是数组）：
 *   `{ "top-row": ["#tab-bar"], "body": ["#playlist"] }`
 *   → 自动视为子 slot 字典，等效于嵌入一个容器组件
 */
object LayoutParser {

    fun parseSlotValue(value: Any): List<ComponentEntry> {
        val arr = when (value) {
            is JSONArray -> value
            is JSONObject -> value.optJSONArray("children")
                ?: throw IllegalArgumentException("Slot object must have a \"children\" array")
            else -> throw IllegalArgumentException("Slot value must be array or object, got: $value")
        }
        return parseComponents(arr)
    }

    private fun parseComponents(arr: JSONArray): List<ComponentEntry> {
        val result = mutableListOf<ComponentEntry>()
        for (i in 0 until arr.length()) {
            val item = arr.get(i)
            when (item) {
                is String -> {
                    val isCustom = item.startsWith("#")
                    val raw = normalizeId(item)
                    if (raw.isBlank()) continue
                    // 支持 "name@cid" 简写
                    val (id, cid) = splitAt(raw, '@')
                    if (id.isNotBlank()) result.add(ComponentEntry(id, cid = cid, isCustom = isCustom))
                }
                is JSONObject -> {
                    val keys = item.keys().asSequence().toList()
                    val firstKey = keys.firstOrNull()

                    if (keys.size == 1 && firstKey != null) {
                        val value = item.get(firstKey)
                        if (value is JSONObject) {
                            // 组件声明：{ "#icon@search-icon": { "icon": "ic_search" } }
                            // cid 只能从 key 的 @ 语法取，不允许在 value 里声明
                            val isCustom = firstKey.startsWith("#")
                            val raw = normalizeId(firstKey)
                            if (raw.isBlank()) continue
                            val (id, cid) = splitAt(raw, '@')
                            if (id.isBlank()) continue
                            val extra = mutableMapOf<String, Any?>()
                            for (k in value.keys()) {
                                when (k) {
                                    "class", "name", "children" -> { /* 保留 key */ }
                                    else -> extra[k] = value.get(k)
                                }
                            }
                            val rawChildren = value.optJSONObject("children")
                            if (rawChildren != null) {
                                extra["children"] = parseChildrenMap(rawChildren)
                            }
                            result.add(ComponentEntry(id, cid = cid, extra = extra, isCustom = isCustom))
                        } else {
                            // value 不是对象 → 尝试作为子 slot 字典
                            val childSlots = parseChildrenMap(item)
                            if (childSlots.isNotEmpty()) {
                                result.add(ComponentEntry("__slot__", extra = mapOf("children" to childSlots)))
                            }
                        }
                    } else {
                        // 多 key → 子 slot 字典：{ "top-row": ["#tab-bar"], "body": ["#playlist"] }
                        val childSlots = parseChildrenMap(item)
                        if (childSlots.isNotEmpty()) {
                            result.add(ComponentEntry("__slot__", extra = mapOf("children" to childSlots)))
                        }
                    }
                }
            }
        }
        return result
    }

    /**
     * 解析 children 字典：每个 key 映射到一个组件数组，与顶层 slot 格式一致。
     * ```json
     * { "slot-a": ["#comp1"], "slot-b": ["#comp2", "#comp3"] }
     * ```
     */
    private fun parseChildrenMap(json: JSONObject): Map<String, List<ComponentEntry>> {
        val result = linkedMapOf<String, List<ComponentEntry>>()
        for (key in json.keys()) {
            val value = json.get(key)
            val entries = when (value) {
                is JSONArray -> parseComponents(value)
                else -> throw IllegalArgumentException("Children slot '$key' must be a JSON array")
            }
            result[key] = entries
        }
        return result
    }

    /** 去掉可选的 # 前缀 */
    private fun normalizeId(s: String): String =
        if (s.startsWith("#")) s.substring(1) else s

    /**
     * 按分隔符拆分字符串，返回 (prefix, suffixOrNull)。
     * 如 "icon@search-icon" → ("icon", "search-icon")；"icon" → ("icon", null)
     */
    private fun splitAt(s: String, sep: Char): Pair<String, String?> {
        val idx = s.indexOf(sep)
        return if (idx >= 0) s.substring(0, idx) to s.substring(idx + 1).ifBlank { null }
        else s to null
    }

    fun readFileContent(file: File): String = removeComments(file.readText())

    fun removeComments(json: String): String {
        val sb = StringBuilder(json.length)
        var i = 0
        var inString = false
        while (i < json.length) {
            val c = json[i]
            if (c == '"') {
                // 统计引号前连续反斜杠数量：奇数个 = 转义引号（不切换字符串状态），偶数个 = 字符串边界
                var backslashes = 0
                var j = i - 1
                while (j >= 0 && json[j] == '\\') { backslashes++; j-- }
                if (backslashes % 2 == 0) inString = !inString
            }
            if (!inString && c == '/' && i + 1 < json.length) {
                val next = json[i + 1]
                if (next == '/') {
                    i += 2; while (i < json.length && json[i] != '\n') i++; continue
                } else if (next == '*') {
                    i += 2
                    while (i + 1 < json.length && !(json[i] == '*' && json[i + 1] == '/')) i++
                    i += 2; continue
                }
            }
            sb.append(c); i++
        }
        return sb.toString()
    }
}

package com.winter.muplayer.config

import android.content.Context
import android.util.Log
import java.io.File

/**
 * 配置预加载缓存。
 *
 * 在 Activity.onCreate 中 setContent 之前调用 [start] 启动 IO 线程加载，
 * StyleConfigLoader 的 init 先检查此缓存，命中则直接使用，零文件 I/O 延迟。
 *
 * 启动流程：
 *   1. 检查 layout.cache 是否存在且最新 → 反序列化，跳过 JSON/CSS 解析
 *   2. 否则读 JSON + CSS 解析 → 写 layout.cache（下次启动直接走 1）
 *
 * 线程安全：@Volatile 保证写线程对读线程可见，初始化后不修改。
 */
object ConfigPreload {

    private const val TAG = "ConfigPreload"

    @Volatile
    var config: ComponentLayout? = null

    @Volatile
    var css: CssRuleTable? = null

    /**
     * 同步尝试加载缓存。必须在 setContent 之前调用。
     * true = 缓存命中，首帧即用真实配置。
     * false = 没有缓存，需要 [start] 异步加载。
     */
    fun loadIfCached(context: Context): Boolean {
        val configDir = configDir(context)
        if (!BinaryCache.isFresh(configDir)) return false

        val t0 = System.nanoTime()
        val cached = BinaryCache.tryRead(configDir) ?: return false

        val elapsedMs = (System.nanoTime() - t0) / 1_000_000.0
        config = cached.first
        css = cached.second
        Log.d(TAG, "缓存命中，%.2fms 反序列化完成".format(elapsedMs))
        return true
    }

    /** 在 IO 线程上加载配置并缓存。可在 setContent 之前调用。 */
    fun start(context: Context) {
        if (config != null) {
            Log.d(TAG, "缓存已在 loadIfCached 中加载，跳过")
            return
        }
        Thread {
            try {
                load(context)
            } catch (_: Exception) {
                // 静默失败，StyleConfigLoader 会走同步回退
            }
        }.apply {
            name = "config-preload"
            isDaemon = true
            start()
        }
    }

    /** 同步加载配置到缓存（慢速路径）。 */
    private fun load(context: Context) {
        val t0 = System.nanoTime()
        val configDir = configDir(context)

        // ── 1. 优先尝试二进制缓存（可能在 start→load 之间已被写入） ──
        if (BinaryCache.isFresh(configDir)) {
            val cached = BinaryCache.tryRead(configDir)
            if (cached != null) {
                config = cached.first
                css = cached.second
                val ms = (System.nanoTime() - t0) / 1_000_000.0
                Log.d(TAG, "后台缓存命中，%.2fms".format(ms))
                return
            }
        }

        // ── 2. 缓存不存在/已过期 → 解析 JSON + CSS ──
        val mainFile = File(configDir, "main.json")
        if (!mainFile.isFile) return

        val (merged, _) = StyleConfigLoader.resolveWithIncludesStatic(
            mainFile, configDir, mutableSetOf()
        )
        val parsedLayout = StyleConfigLoader.parseConfigObjectStatic(merged)
        val cssRules = loadCssStatic(configDir)

        config = parsedLayout
        css = cssRules

        val parseMs = (System.nanoTime() - t0) / 1_000_000.0
        Log.d(TAG, "JSON+CSS 解析完成，%.2fms".format(parseMs))

        // ── 3. 写二进制缓存（下次启动走快速路径） ──
        try {
            val t1 = System.nanoTime()
            BinaryCache.write(configDir, parsedLayout, cssRules)
            val writeMs = (System.nanoTime() - t1) / 1_000_000.0
            Log.d(TAG, "缓存写入完成，%.2fms".format(writeMs))
        } catch (_: Exception) { }
    }

    private fun configDir(context: Context): File {
        val extDir = context.getExternalFilesDir(null)
        return if (extDir != null) File(extDir, "config")
        else File(context.filesDir, "config")
    }

    private fun loadCssStatic(configDir: File): CssRuleTable {
        if (!configDir.isDirectory) return CssRuleTable()
        val cssFiles = configDir.listFiles { f -> f.extension == "css" }
            ?.sortedBy { it.name } ?: return CssRuleTable()
        val merged = mutableMapOf<String, Map<String, String>>()
        for (file in cssFiles) {
            try {
                merged.putAll(CssParser.parse(file.readText()))
            } catch (_: Exception) { }
        }
        return CssRuleTable(rules = merged)
    }
}

